package org.fitznet;

import lombok.extern.slf4j.Slf4j;
import net.dv8tion.jda.api.JDA;
import net.dv8tion.jda.api.JDABuilder;
import net.dv8tion.jda.api.OnlineStatus;
import net.dv8tion.jda.api.entities.Activity;
import org.fitznet.commands.ConfigCommands;
import org.fitznet.listener.LoginListener;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@Slf4j
@RestController
@RequestMapping("/bot")
public class BotController {

    @Autowired
    private Main mainApp;

    @Value("${discord.bot.token}")
    private String token;

    @PostMapping("/startup")
    public String startup() {
        JDA jda = mainApp.getJda();
        if (jda == null || jda.getStatus() == JDA.Status.SHUTDOWN) {
            try {
                jda = JDABuilder.createDefault(token)
                        .setStatus(OnlineStatus.ONLINE)
                        .setActivity(Activity.watching("The server... at all times"))
                        .build().awaitReady();

                // Add event listeners
                jda.addEventListener(new LoginListener(jda));
                jda.addEventListener(new ConfigCommands());

                // Small delay to ensure guild cache is fully populated
                Thread.sleep(2000);

                // Register commands for all current guilds immediately
                if (jda.getGuilds().isEmpty()) {
                    log.warn("No guilds found after startup - guild cache may not be ready yet");
                }

                for (var guild : jda.getGuilds()) {
                    guild.updateCommands()
                        .addCommands(ConfigCommands.getCommands())
                        .queue(
                            success -> log.info("Commands registered for guild: {} ({})", guild.getName(), guild.getId()),
                            error -> log.error("Failed to register commands for guild {}: {}", guild.getName(), error.getMessage())
                        );
                }

                // Also register globally for new servers (backup)
                jda.updateCommands().addCommands(ConfigCommands.getCommands()).queue(
                    success -> log.info("Global commands registered successfully"),
                    error -> log.error("Failed to register global commands: {}", error.getMessage())
                );

                return String.format("Bot started successfully! Commands registered for %d guilds immediately.", jda.getGuilds().size());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return "Failed to start bot: " + e.getMessage();
            }
        }
        return "Bot is already running.";
    }

    @PostMapping("/force-update-commands")
    public String forceUpdateCommands() {
        JDA jda = mainApp.getJda();
        if (jda == null) {
            return "Bot is not running!";
        }

        int guildCount = 0;
        for (var guild : jda.getGuilds()) {
            guild.updateCommands()
                .addCommands(ConfigCommands.getCommands())
                .queue(
                    success -> log.info("Force updated commands for guild: {}", guild.getName()),
                    error -> log.error("Failed to force update commands for guild {}: {}", guild.getName(), error.getMessage())
                );
            guildCount++;
        }

        return String.format("Force updated commands for %d guilds. Commands should appear immediately!", guildCount);
    }

    @PostMapping("/register-guild-commands/{guildId}")
    public String registerGuildCommands(@PathVariable String guildId) {
        JDA jda = mainApp.getJda();
        if (jda == null) {
            return "Bot is not running!";
        }

        try {
            jda.getGuildById(guildId).updateCommands()
                .addCommands(ConfigCommands.getCommands())
                .queue(
                    success -> log.info("Guild commands registered successfully for guild {}", guildId),
                    error -> log.error("Failed to register guild commands for {}: {}", guildId, error.getMessage())
                );
            return "Guild commands registered for " + guildId + " (should appear immediately)";
        } catch (Exception e) {
            return "Error registering guild commands: " + e.getMessage();
        }
    }

    @PostMapping("/shutdown")
    public String shutdown() {
        JDA jda = mainApp.getJda();
        if (jda != null && jda.getStatus() != JDA.Status.SHUTDOWN) {
            jda.shutdown();
            return "Bot is shutting down.";
        }
        return "Bot is already shut down.";
    }

    @GetMapping("/status")
    public String getStatus() {
        JDA jda = mainApp.getJda();
        if (jda == null) {
            return "Bot is not initialized.";
        }
        return "Bot status: " + jda.getStatus();
    }
}

package org.fitznet;

import lombok.extern.slf4j.Slf4j;
import org.fitznet.service.BotService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@Slf4j
@RestController
@RequestMapping("/bot")
public class BotController {

    private final BotService botService;

    @Autowired
    public BotController(BotService botService) {
        this.botService = botService;
    }

    @PostMapping("/startup")
    public String startup() {
        return botService.startBot();
    }

    @PostMapping("/force-update-commands")
    public String forceUpdateCommands() {
        return botService.forceUpdateCommands();
    }

    @PostMapping("/register-guild-commands/{guildId}")
    public String registerGuildCommands(@PathVariable String guildId) {
        return botService.registerGuildCommands(guildId);
    }

    @PostMapping("/shutdown")
    public String shutdown() {
        return botService.stopBot();
    }

    @GetMapping("/status")
    public String getStatus() {
        return botService.getStatus();
    }
}

package org.fitznet.data;

import com.fasterxml.jackson.core.type.TypeReference;
import lombok.extern.slf4j.Slf4j;
import org.fitznet.util.JsonUtils;

import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import static org.fitznet.util.Constants.TOTALLY_LEGIT_DATABASE_FILENAME;

@Slf4j
public class VoiceJoinDatabase {
    private final Map<Long, Long> voiceJoinCounts = new ConcurrentHashMap<>();
    private final String databaseFile;

    public VoiceJoinDatabase() {
        this.databaseFile = TOTALLY_LEGIT_DATABASE_FILENAME;
        loadData();
    }

    /**
     * Load voice join counts from JSON file
     */
    private void loadData() {
        try {
            File file = new File(databaseFile);
            if (file.exists() && file.length() > 0) {
                Map<Long, Long> loadedData = JsonUtils.MAPPER.readValue(file, new TypeReference<>() {
                });
                voiceJoinCounts.putAll(loadedData);
                log.info("Loaded {} user voice join counts from database", loadedData.size());
            } else {
                boolean isNewFileCreated = file.createNewFile();
                log.info("Created new voice join database file: {}", isNewFileCreated);
            }
        } catch (IOException e) {
            log.error("Failed to load voice join data from file. Starting with empty database.", e);
        }
    }

    /**
     * Save voice join counts to JSON file
     */
    public void saveData() {
        try {
            JsonUtils.MAPPER.writeValue(new File(databaseFile), voiceJoinCounts);
            log.debug("Voice join counts saved to database successfully");
        } catch (IOException e) {
            log.warn("Failed to save voice join counts to file", e);
        }
    }

    /**
     * Get the current voice join count for a user
     * @param userId Discord user ID
     * @return Current join count, or 0 if user not found
     */
    public long getVoiceJoinCount(long userId) {
        return voiceJoinCounts.getOrDefault(userId, 0L);
    }

    /**
     * Increment voice join count for a user and return the new count
     * @param userId Discord user ID
     * @return New join count after incrementing
     */
    public long incrementVoiceJoinCount(long userId) {
        long newCount = voiceJoinCounts.compute(userId, (key, oldCount) ->
            oldCount == null ? 1L : oldCount + 1L);
        saveData(); // Auto-save after each increment
        return newCount;
    }

    /**
     * Get all voice join counts (read-only copy)
     * @return Map of user IDs to join counts
     */
    public Map<Long, Long> getAllCounts() {
        return new HashMap<>(voiceJoinCounts);
    }

    /**
     * Check if a user exists in the database
     * @param userId Discord user ID
     * @return true if user has at least one voice join recorded
     */
    public boolean userExists(long userId) {
        return voiceJoinCounts.containsKey(userId);
    }
}

package org.fitznet.data;

import com.fasterxml.jackson.core.type.TypeReference;
import lombok.extern.slf4j.Slf4j;
import org.fitznet.util.JsonUtils;

import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Database for tracking voice channel join counts per guild and user.
 * Stores data in separate JSON files for each Discord server to ensure proper isolation.
 */
@Slf4j
public class VoiceJoinDatabase {
    private final Map<Long, Map<Long, Long>> guildUserCounts = new ConcurrentHashMap<>();
    private final String dataDirectory;

    public VoiceJoinDatabase() {
        this.dataDirectory = "data";
        createDataDirectory();
        loadAllGuildData();
    }

    /**
     * Creates the data directory if it doesn't exist.
     */
    private void createDataDirectory() {
        File dir = new File(dataDirectory);
        if (!dir.exists()) {
            boolean created = dir.mkdirs();
            log.info("Created data directory: {}", created);
        }
    }

    /**
     * Loads voice join data for all existing guild files.
     */
    private void loadAllGuildData() {
        File dir = new File(dataDirectory);
        File[] files = dir.listFiles((d, name) -> name.startsWith("guild_") && name.endsWith(".json"));

        if (files != null) {
            for (File file : files) {
                String filename = file.getName();
                String guildIdStr = filename.substring(6, filename.length() - 5);
                try {
                    long guildId = Long.parseLong(guildIdStr);
                    loadGuildData(guildId);
                } catch (NumberFormatException e) {
                    log.warn("Invalid guild file name: {}", filename);
                }
            }
        }
    }

    /**
     * Loads voice join data for a specific guild.
     *
     * @param guildId the Discord guild ID
     */
    private void loadGuildData(long guildId) {
        String filename = getGuildFilename(guildId);
        try {
            File file = new File(filename);
            if (file.exists() && file.length() > 0) {
                Map<Long, Long> userData = JsonUtils.MAPPER.readValue(file, new TypeReference<>() {
                });
                guildUserCounts.put(guildId, new ConcurrentHashMap<>(userData));
                log.info("Loaded {} user voice join counts for guild {}", userData.size(), guildId);
            } else {
                guildUserCounts.put(guildId, new ConcurrentHashMap<>());
                if (!file.exists()) {
                    boolean created = file.createNewFile();
                    log.info("Created new guild database file for {}: {}", guildId, created);
                }
            }
        } catch (IOException e) {
            log.error("Failed to load voice join data for guild {}. Starting with empty database.", guildId, e);
            guildUserCounts.put(guildId, new ConcurrentHashMap<>());
        }
    }

    /**
     * Saves voice join data for a specific guild.
     *
     * @param guildId the Discord guild ID
     */
    private void saveGuildData(long guildId) {
        String filename = getGuildFilename(guildId);
        try {
            Map<Long, Long> userData = guildUserCounts.get(guildId);
            if (userData != null) {
                JsonUtils.MAPPER.writeValue(new File(filename), userData);
                log.debug("Voice join counts saved for guild {} successfully", guildId);
            }
        } catch (IOException e) {
            log.warn("Failed to save voice join counts for guild {}", guildId, e);
        }
    }

    /**
     * Generates the filename for a guild's data file.
     *
     * @param guildId the Discord guild ID
     * @return the filename for the guild's data
     */
    private String getGuildFilename(long guildId) {
        return dataDirectory + "/guild_" + guildId + ".json";
    }

    /**
     * Gets the current voice join count for a user in a specific guild.
     *
     * @param guildId the Discord guild ID
     * @param userId  the Discord user ID
     * @return current join count, or 0 if user not found
     */
    public long getVoiceJoinCount(long guildId, long userId) {
        return guildUserCounts
                .getOrDefault(guildId, new ConcurrentHashMap<>())
                .getOrDefault(userId, 0L);
    }

    /**
     * Increments voice join count for a user in a specific guild.
     *
     * @param guildId the Discord guild ID
     * @param userId  the Discord user ID
     * @return new join count after incrementing
     */
    public long incrementVoiceJoinCount(long guildId, long userId) {
        guildUserCounts.computeIfAbsent(guildId, k -> new ConcurrentHashMap<>());

        long newCount = guildUserCounts.get(guildId).compute(userId, (key, oldCount) ->
                oldCount == null ? 1L : oldCount + 1L);

        saveGuildData(guildId);
        return newCount;
    }

    /**
     * Gets all voice join counts for a specific guild.
     *
     * @param guildId the Discord guild ID
     * @return map of user IDs to join counts for the guild
     */
    public Map<Long, Long> getGuildCounts(long guildId) {
        Map<Long, Long> guildData = guildUserCounts.get(guildId);
        return guildData != null ? new HashMap<>(guildData) : new HashMap<>();
    }

    /**
     * Checks if a user exists in a guild's database.
     *
     * @param guildId the Discord guild ID
     * @param userId  the Discord user ID
     * @return true if user has at least one voice join recorded in the guild
     */
    public boolean userExists(long guildId, long userId) {
        Map<Long, Long> guildData = guildUserCounts.get(guildId);
        return guildData != null && guildData.containsKey(userId);
    }
}

package org.fitznet.data.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.HashMap;
import java.util.Map;

/**
 * POJO representing the complete guild configurations data structure.
 * Maps guild IDs to their respective configurations.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class GuildConfigurations {

    /**
     * Map of guild ID to guild configuration.
     * Key: Discord guild ID (as Long)
     * Value: Guild-specific configuration
     */
    @Builder.Default
    private Map<Long, GuildConfig> guilds = new HashMap<>();

    /**
     * Gets configuration for a specific guild.
     * 
     * @param guildId Discord guild ID
     * @return guild configuration or null if not found
     */
    public GuildConfig getGuildConfig(Long guildId) {
        return guilds.get(guildId);
    }

    /**
     * Sets configuration for a specific guild.
     * 
     * @param guildId Discord guild ID
     * @param config guild configuration
     */
    public void setGuildConfig(Long guildId, GuildConfig config) {
        guilds.put(guildId, config);
    }

    /**
     * Gets or creates configuration for a guild.
     * 
     * @param guildId Discord guild ID
     * @return existing or new guild configuration
     */
    public GuildConfig getOrCreateGuildConfig(Long guildId) {
        return guilds.computeIfAbsent(guildId, k -> new GuildConfig());
    }

    /**
     * Removes configuration for a guild.
     * 
     * @param guildId Discord guild ID
     * @return removed configuration or null if not found
     */
    public GuildConfig removeGuildConfig(Long guildId) {
        return guilds.remove(guildId);
    }

    /**
     * Checks if a guild has any configuration.
     * 
     * @param guildId Discord guild ID
     * @return true if guild has configuration
     */
    public boolean hasGuildConfig(Long guildId) {
        return guilds.containsKey(guildId);
    }

    /**
     * Gets the number of configured guilds.
     * 
     * @return number of guilds with configurations
     */
    public int getGuildCount() {
        return guilds.size();
    }
}

package org.fitznet;

import org.fitznet.service.BotService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.test.context.TestPropertySource;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@SpringBootTest
@TestPropertySource(properties = "discord.bot.token=test-token")
class MainTest {

    @MockBean
    private BotService mockBotService;

    @Autowired
    private BotController botController;

    @Test
    void testBotControllerIsCreated() {
        assertNotNull(botController);
    }

    @Test
    void testShutdownEndpoint() {
        // Mock the BotService response
        when(mockBotService.stopBot()).thenReturn("Bot is shutting down.");

        String result = botController.shutdown();

        assertNotNull(result);
        assertEquals("Bot is shutting down.", result);

        // Verify that BotService.stopBot() was called
        verify(mockBotService).stopBot();
    }
}

